    /**
     * Method to retrieve the Site via SiteFetchOneSummary
     * @param 	summary SiteFetchOneSummary 
     * @return 	SiteFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Site getSite( SiteFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "SiteFetchOneSummary arg cannot be null" );
    	
    	Site entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Site
        	// --------------------------------------
        	CompletableFuture<Site> futureEntity = queryGateway.query(new FindSiteQuery( new LoadSiteFilter( summary.getSiteId() ) ), ResponseTypes.instanceOf(Site.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Site with id " + summary.getSiteId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


